// Pilot prices; checkout is a local demonstration, not a payment integration.
const paidPlans=[
{id:'teacher-services',role:'teacher',name:'Teach & Earn',purpose:'Coaching & other services',price:499,features:['Up to 3 active service listings','Matching learner requirements','Demo-session requests and enquiries','Consent-based connection requests'],limit:'3 service listings'},
{id:'institution-hiring',role:'institution',name:'Hire Talent',purpose:'Teacher & faculty recruitment',price:1499,features:['Up to 5 active job openings','Discover candidates by relevant skills','Shortlists and contact requests','Training-partner discovery'],limit:'5 active job openings'},
{id:'institution-admissions',role:'institution',name:'Grow Admissions',purpose:'Admission promotion',price:999,features:['Institution profile and programme listings','Admission enquiries','Campus-visit requests','Training-partner discovery'],limit:'Institution and programme listings'},
{id:'institution-both',role:'institution',name:'Institution Complete',purpose:'Hiring + admission promotion',price:1999,features:['Everything in Hire Talent','Everything in Grow Admissions','Up to 5 active job openings','Training-partner discovery'],limit:'5 active job openings + admission features',bundle:true,saving:499},
{id:'training-learners',role:'training',name:'Reach Learners',purpose:'Individual learner enrolment',price:999,features:['Up to 10 active courses','Discovery by skills and learning goals','Learner enquiries and demo requests','Course and trainer profiles'],limit:'10 active courses'},
{id:'training-partners',role:'training',name:'Build Partnerships',purpose:'Institutional training business',price:1499,features:['Discover institutional training needs','Respond with programme proposals','Partnership connection requests','Showcase training expertise'],limit:'Institutional business features'},
{id:'training-both',role:'training',name:'Training Complete',purpose:'Learner enrolment + institutional business',price:1999,features:['Everything in Reach Learners','Everything in Build Partnerships','Up to 10 active courses','Individual and institutional enquiries'],limit:'10 active courses + business features',bundle:true,saving:499}
];
const billing={audience:null,orders:[],selected:null,method:'UPI',sequence:0};
function money(n){return '₹'+n.toLocaleString('en-IN')}
function chooseAudience(role){billing.audience=role;plans()}
function priceCard(p){return `<article class="card plan ${p.bundle?'recommended':''}"><div class="section-top"><span class="eyebrow">${p.purpose}</span>${p.bundle?'<span class="badge">BUNDLE</span>':''}</div><h3>${p.name}</h3><div class="plan-price">${money(p.price)}<small class="per-month"> / month</small></div><p class="muted price-caption">Monthly prepaid · Manual renewal</p>${p.bundle?`<div class="bundle-saving">Save ${money(p.saving)} / month versus both separately</div>`:''}<ul>${p.features.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn ${p.bundle?'':'light'}" onclick="startCheckout('${p.id}')">Try sample checkout →</button><p class="bottom-note">Pilot price proposal. No real charge.</p></article>`}
plans=function(){const audience=billing.audience||state.role;const choices=[['learner','Students & parents'],['teacher','Teachers & experts'],['institution','Schools & colleges'],['training','Training providers']];const learner=audience==='learner';$('#main').innerHTML=intro('TALIND MEMBERSHIP','Choose the opportunity you want.','Pay for the purpose that helps you grow. Learning discovery and teacher job seeking stay free.','Pilot pricing · Sample only')+`<div class="tabs" role="group" aria-label="Choose membership category">${choices.map(([k,v])=>`<button class="chip ${k===audience?'active':''}" onclick="chooseAudience('${k}')" aria-pressed="${k===audience}">${v}</button>`).join('')}</div><div class="pricing-context"><span>${roleNames[audience]}</span><span>Monthly plans · No automatic debit</span></div><div class="cards pricing-cards">${learner?`<article class="card plan recommended"><span class="eyebrow">LEARN & DISCOVER</span><h3>Your next possibility</h3><div class="plan-price">Always free</div><ul><li>Find tuition, coaching and skills training</li><li>Explore schools and colleges</li><li>Compare and shortlist profiles</li><li>Post needs and send enquiries</li></ul><button class="btn" onclick="changeRole('learner')">Explore free access →</button><p class="bottom-note">Tuition and course fees charged by providers are separate.</p></article><article class="card plan"><span class="eyebrow">YOUR CONNECTIONS, YOUR CHOICE</span><h3>Choose who can contact you.</h3><p class="muted">Providers can discover relevant learning requirements. Contact details are shared only when the adult learner or parent accepts a connection.</p><p class="muted">A provider subscription does not grant unrestricted access to children’s profiles.</p></article>`:audience==='teacher'?`<article class="card plan"><span class="eyebrow">FIND YOUR NEXT ROLE</span><h3>Teacher Job Seeker</h3><div class="plan-price">Free</div><ul><li>Create your professional skill profile</li><li>Explore teaching and faculty jobs</li><li>Apply for relevant roles</li><li>Shortlist suitable opportunities</li></ul><button class="btn outline" onclick="changeRole('teacher')">Explore free job seeking →</button><p class="bottom-note">Offering tuition, coaching or other services uses the paid plan.</p></article>${paidPlans.filter(p=>p.role===audience).map(priceCard).join('')}`:paidPlans.filter(p=>p.role===audience).map(priceCard).join('')}</div><div class="split"><section class="panel"><h2>Simple payment choices</h2><div class="payment-badges"><span>UPI</span><span>Debit / Credit card</span><span>Net banking</span></div><p class="muted">Preview a monthly prepaid membership. Renew manually when it expires; there is no automatic debit.</p><p class="bottom-note">Payment methods are demonstrations. Live payment-gateway and tax configuration are pending.</p></section><section class="panel"><h2>What your membership covers</h2><p class="muted">Talind membership provides access to the listed discovery, listing and enquiry features. Hires, admissions and enrolments are not guaranteed.</p><p class="muted">Learners pay tuition and course fees directly to their chosen provider during the initial phase.</p></section></div><section class="panel"><div class="section-top"><h2>Your demo memberships</h2><span class="count">Session only</span></div>${billing.orders.length?billing.orders.map((o,i)=>`<div class="row"><div><strong>${esc(o.plan.name)}</strong><p>${money(o.plan.price)} · ${esc(o.method)} · ${esc(o.date)}<br>Simulation only · Manual renewal</p></div><button class="btn outline" onclick="showReceipt(${i})">View demo receipt</button></div>`).join(''):'<p class="muted">Try a paid plan to see the checkout and sample receipt here. No payment is collected.</p>'}</section><p class="bottom-note">All amounts are proposed pilot membership prices in INR. Applicable tax and the final payable amount will be configured before live payments. Paid promotion will be labelled separately from match relevance.</p>`}
function startCheckout(id){const p=paidPlans.find(x=>x.id===id);if(!p)return;billing.selected=p;billing.method='UPI';modal(`<span class="eyebrow">SAMPLE CHECKOUT · STEP 1 OF 2</span><h2>${p.name}</h2><p class="muted">${p.purpose} · ${roleNames[p.role]}</p><div class="checkout-summary"><div><span>Monthly membership</span><strong>${money(p.price)}</strong></div><div><span>Billing</span><span>Prepaid · Manual renewal</span></div><div><span>Applicable tax</span><span>Not configured in sample</span></div><div class="checkout-total"><span>Illustrative base total</span><strong>${money(p.price)}</strong></div></div><div class="notice">No money will be collected. Do not enter a UPI ID, card number, PIN, OTP or banking credentials. This sample does not connect to a bank.</div><form id="checkout-form"><div class="fields"><label class="full">Sample billing name<input name="billingName" required maxlength="120" value="${esc(state.profiles[p.role].name)}"></label></div><fieldset class="choice-group payment-options"><legend>Choose a payment method</legend>${['UPI','Debit / Credit card','Net banking'].map((m,i)=>`<label class="check-row"><input type="radio" name="paymentMethod" value="${m}" ${i===0?'checked':''}><span><strong>${m}</strong><small>${i===0?'UPI app payment in the future live checkout':i===1?'Secure gateway checkout when live':'Bank selection at the gateway when live'}</small></span></label>`).join('')}</fieldset><label class="check-row"><input type="checkbox" name="demoConsent" required><span>I understand this is a simulated membership checkout and no payment is made.</span></label><button class="btn" type="submit">Review sample order →</button></form>`);$('#checkout-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);billing.method=data.get('paymentMethod');billing.billingName=data.get('billingName').trim();if(!['UPI','Debit / Credit card','Net banking'].includes(billing.method)||!billing.billingName)return;reviewCheckout()}}
function reviewCheckout(){const p=billing.selected;$('#modal-body').innerHTML=`<span class="eyebrow">SAMPLE CHECKOUT · STEP 2 OF 2</span><h2>Review your sample order.</h2><div class="checkout-summary"><div><span>Plan</span><strong>${p.name}</strong></div><div><span>Billing name</span><span>${esc(billing.billingName)}</span></div><div><span>Method</span><span>${esc(billing.method)}</span></div><div><span>Includes</span><span>${p.limit}</span></div><div><span>Renewal</span><span>Monthly, manual</span></div><div><span>Tax</span><span>Pending configuration</span></div><div class="checkout-total"><span>Illustrative base total</span><strong>${money(p.price)}</strong></div></div><p class="muted">This demonstrates the checkout experience only. No real subscription, payment or invoice will be created.</p><div class="dialog-actions"><button class="btn" onclick="finishDemoCheckout()">Simulate successful checkout</button><button class="btn outline" onclick="startCheckout('${p.id}')">Change details</button></div>`}
function finishDemoCheckout(){const p=billing.selected;if(!p)return;const o={id:'DEMO-'+String(++billing.sequence).padStart(4,'0'),plan:{...p},method:billing.method,name:billing.billingName,date:new Date().toLocaleDateString('en-IN'),created:new Date().toISOString()};billing.orders.push(o);billing.selected=null;showReceipt(billing.orders.length-1);toast('Demo checkout completed. No payment was taken.');if(location.hash==='#plans')plans()}
function showReceipt(i){const o=billing.orders[i];if(!o)return;if(!$('#modal').open)$('#modal').showModal();$('#modal-body').innerHTML=`<span class="eyebrow">CHECKOUT SIMULATED</span><h2>Your sample receipt is ready.</h2><div class="notice success">No payment received. This is not a tax invoice or proof of payment.</div><div class="checkout-summary"><div><span>Demo reference</span><strong>${o.id}</strong></div><div><span>Plan</span><span>${o.plan.name}</span></div><div><span>Billing name</span><span>${esc(o.name)}</span></div><div><span>Date</span><span>${o.date}</span></div><div><span>Method demonstrated</span><span>${esc(o.method)}</span></div><div><span>Illustrative membership amount</span><strong>${money(o.plan.price)}</strong></div><div><span>Actual amount charged</span><strong>₹0 — simulation only</strong></div></div><p class="muted">Manual monthly renewal. No automatic debit. Tax and live payment collection are not configured.</p><div class="dialog-actions"><button class="btn" onclick="downloadDemoReceipt(${i})">Download demo receipt</button><button class="btn outline" onclick="$('#modal').close();navigate('plans')">Back to membership</button></div>`}
function downloadDemoReceipt(i){const o=billing.orders[i];if(!o)return;const text=['TALIND — DEMO RECEIPT','NOT A TAX INVOICE OR PROOF OF PAYMENT','', 'Reference: '+o.id,'Date: '+o.date,'Billing name: '+o.name,'Plan: '+o.plan.name,'Payment method demonstrated: '+o.method,'Illustrative membership price: INR '+o.plan.price,'Actual amount charged: INR 0 — simulation only','Tax: not configured','Renewal: monthly, manual','No real membership or payment has been created.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Talind-'+o.id+'-sample-receipt.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const workspaceBeforePricing=workspace;workspace=function(){workspaceBeforePricing();if(state.role!=='learner')$('#main').insertAdjacentHTML('beforeend',`<section class="panel"><span class="eyebrow">MEMBERSHIP</span><h2 style="margin-top:12px">Choose access for your purpose.</h2><p class="muted">${state.role==='teacher'?'Job seeking is free. Coaching and service listings start at ₹499 per month.':'Single-purpose plans start at ₹999 per month. Combine both purposes for ₹1,999 per month.'}</p><button class="btn light" onclick="billing.audience=state.role;navigate('plans')">Compare plans & try checkout →</button></section>`)};
if(location.hash==='#plans'||location.hash==='#workspace')render();
